const TIER_LABEL = { critical: "🔴 CRITICAL", watch: "🟡 WATCH", ok: "OK" };
const TIER_LABEL_HTML = { critical: "CRITICAL", watch: "WATCH", ok: "OK" };
export function renderMarkdown(items) {
    if (items.length === 0)
        return "# Churnlight — Weekly Risk List\n\nNothing flagged this week. 🎉\n";
    let out = `# Churnlight — Weekly Risk List\n\n${items.length} account(s) need attention.\n\n---\n`;
    for (const it of items) {
        out += `\n## ${TIER_LABEL[it.tier]} ${it.account.name} — $${it.account.mrr.toLocaleString()}/mo MRR\n`;
        for (const s of it.signals) {
            out += `- **Why:** ${s.reason}\n  **Do:** ${s.action}\n`;
        }
        out += `  _risk score: ${it.riskScore}_\n`;
    }
    return out;
}
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
export function renderEmailHtml(items, title = "Churnlight — Weekly Risk List") {
    const rows = items
        .map((it) => `
    <tr style="border-bottom:1px solid #eee">
      <td style="padding:10px;vertical-align:top">
        <div style="font-weight:700">${esc(it.account.name)}
          <span style="background:${it.tier === "critical" ? "#fee2e2" : "#fef9c3"};color:${it.tier === "critical" ? "#b91c1c" : "#854d0e"};
          padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;margin-left:6px">${TIER_LABEL_HTML[it.tier]}</span>
        </div>
        <div style="color:#666;font-size:13px">$${it.account.mrr.toLocaleString()}/mo · renewal ${esc(it.account.renewalOn)}</div>
        ${it.signals
        .map((s) => `<div style="margin-top:6px;font-size:14px"><strong>Why:</strong> ${esc(s.reason)}<br/><strong>Do:</strong> ${esc(s.action)}</div>`)
        .join("")}
      </td>
    </tr>`)
        .join("");
    return `<!doctype html><html><body style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;color:#111">
  <h2 style="margin:0 0 4px">${esc(title)}</h2>
  <p style="color:#666;font-size:14px;margin-top:0">${items.length} account(s) flagged. Every reason comes with a next action — that is the whole point.</p>
  <table style="border-collapse:collapse;width:100%">${rows || '<tr><td style="padding:20px;color:#666">Nothing flagged this week. 🎉</td></tr>'}</table>
  <p style="color:#999;font-size:12px;margin-top:24px">Generated by Churnlight — rules you can read and edit. No black-box scores.</p>
</body></html>`;
}
